with web_events_by_session as (select session_id, max(duration_sec) - min(duration_sec) duration_sec_range, round(stddev(duration_sec), 2) stddev_duration_sec from web_events group by session_id) select sessions.started_at, sessions.device, web_events_by_session.duration_sec_range, web_events_by_session.stddev_duration_sec from sessions left join web_events_by_session on sessions.id = web_events_by_session.session_id where web_events_by_session.stddev_duration_sec >= 62 order by web_events_by_session.stddev_duration_sec desc
